//! ES0392 Rev 15: the errata of die 0x450 (STM32H742/H743/H750/H753, RM0433), one entry
//! per row of the sheet's summary of device limitations, transcribed on
//! 2026-11-15 (ADR-010). Hand facts: edit an entry's handling as it is reviewed.
//!
//! Requirements: GLUE-007, GLUE-009

use crate::errata::{Erratum, Handling::*, Sheet, SheetStatus};

pub const ERRATA_SHEET: Sheet = Sheet {
    name: "ES0392",
    revision: 15,
    revisions: &[(0x1003, "Y, W"), (0x2001, "X"), (0x2003, "V")],
};

macro_rules! erratum {
    ($section:literal, $title:literal, [$($rev:literal),*], $status:ident, $handling:expr, [$($req:literal),*]) => {
        Erratum {
            sheet: &ERRATA_SHEET,
            section: $section,
            title: $title,
            affected: &[$($rev),*],
            status: SheetStatus::$status,
            handling: $handling,
            requirements: &[$($req),*],
        }
    };
}

/// ES0392 2.2.10, named for the code that acts on it.
#[rustfmt::skip]
pub const ES0392_2_2_10: Erratum = erratum!("2.2.10", "Reading from AXI SRAM may lead to data read corruption", [0x1003], Workaround, Open("no ES0392 2.2.10 workaround for rev-Y/W H7s"), []);

